<p class="has-text-align-center" style="margin-top:24px">速さの記号は、平日12時台と18時台に各3日ずつ測った下り速度の中央値です。◎＝動画が止まらなかった／○＝ときどき画質が落ちた／△＝止まることがあった。</p>
<!-- /wp:paragraph -->
<!-- wp:wdl/lw-space-1 {"pcHeight":80,"tbHeight":64,"spHeight":40} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:80px"></div><div class="tb" style="height:64px"></div><div class="sp" style="height:40px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:wdl/lw-pr-custom-title-13 {"mainTitle":"使い方ごとの目安","subTitle":"FOR YOU","headingLevel":2,"colorMain":"#16305c"} -->
<div class="wp-block-wdl-lw-pr-custom-title-13 lw-pr-custom-title-13" style="--color-main:#16305c"><h2 class="ttl"><span class="sub">FOR YOU</span><span class="main">使い方ごとの目安</span><div class="left"></div><div class="right"></div></h2></div>
<!-- /wp:wdl/lw-pr-custom-title-13 -->
<!-- wp:wdl/lw-space-1 {"pcHeight":16,"tbHeight":16,"spHeight":12} -->
