<!-- /wp:wdl/lw-space-1 -->
<!-- wp:paragraph {"align":"center","style":{"spacing":{"margin":{"top":"28px","bottom":"24px"}}}} -->
<p class="has-text-align-center" style="margin-top:28px;margin-bottom:24px">トップページで選んだ4つの使い方に、上の表を当てはめたものです。</p>
<!-- /wp:paragraph -->
<!-- wp:wdl/lw-pr-custom-title-11 {"mainTitle":"家ではWi-Fi、3GBで足りる","subTitle":"CASE 1","headingLevel":3,"colorMain":"#16305c","borderRadius":8,"maxWidth":900,"minHeightPc":96,"minHeightTb":88,"minHeightSp":76} -->
<div class="wp-block-wdl-lw-pr-custom-title-11 lw-pr-custom-title-11" style="--color-main:#16305c;max-width:900px;width:100%;margin:1em auto;--min-height-pc:96px;--min-height-tb:88px;--min-height-sp:76px" id="gb3"><h3 class="ttl" style="border-radius:8px"><span class="sub">CASE 1</span><span class="main">家ではWi-Fi、3GBで足りる</span></h3></div>
<!-- /wp:wdl/lw-pr-custom-title-11 -->
<!-- wp:paragraph {"style":{"color":{"text":"#1f2733"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#1f2733;font-size:16px;line-height:1.9">外では地図と連絡くらい、という人です。ここは A社と D社の争いで、差は月90円ほど。<strong>昼に動画を見ないなら A社のほうが安く収まります。</strong>3GBを超えた月だけ1GBずつ買い足す使い方もできます（1GBあたり220〜550円）。</p>
<!-- /wp:paragraph -->
